posts.body:
Target effects apply whenever the action hits, regardless of damage.
Depending on exactly what you want to do, one of these workarounds might be OK:
You could set the skill's
Success
rate to, say, 70%. That would give it a constant 30% chance of failing on
any
target.
You could set the skill's
Hit Type
to Physical or Magical, and give the enemy high Evasion/Reflection for that hit type to reduce the hit chance for all actions of that type.
Otherwise, like Andar says, you'd want a suitable plugin.
Here's something untested, in case it helps:
Spoiler:
plugin code
JavaScript:
/*:
 * @target MV MZ
 * @plugindesc Adds <resist escape: X> notetag for trait objects.
 * @author Caethyril
 * @url https://forums.rpgmakerweb.com/threads/173071/
 * @help Actor/Enemy/Class/Weapon/Armor/State notetag:
 *        <resist escape: X>
 *   e.g. <resist escape: 80> = 80% escape resistance
 *
 * Free to use and/or modify for any project, no credit required.
 */
;void (function() => {
"use strict";
  /** Tag label. @type {string} */
  const TAG_NAME = "resist escape";

  /** Tag processing methods. */
  const tag = Object.freeze({

    /**
     * @param {object} o Trait object from which to parse tag data.
     * @returns {number} Tag value, or `0` if no tag.
     */
    parse: function(o) {
      if (o) {  // jic
        const v = parseInt(o.meta[TAG_NAME], 10);
        if (v)
          return v / 100;
      }
      return 0;
    },

    /**
     * Used with `Array#reduce`.
     * @param {number} a Value 1.
     * @param {number} c Value 2.
     * @param {number} [n] Index of value `c` in source array.
     * @returns {number} Combined value.
     */
    combine: function(a, c, n) {
      // return a + c;  // additive
      return 1 - (1 - a) * (1 - c);  // multiplicative
    },

    /**
     * @param {number[]} values Array of parsed tag values.
     * @returns {number} Final value.
     */
    reduce: function(values) {
      return values.reduce(tag.combine, 0);
    }

  });

  /**
   * @param {Game_Battler} battler Determine this battler's resistance.
   * @returns {number} Escape effect resistance for `battler`.
   */
  const getResistEscape = function(battler) {
    if (!battler)  // jic
      return 0;
    return tag.reduce(Array.from(
      battler.traitObjects(), tag.parse
    ));
  };

  // Patch - intercept Escape effect processing to apply resistance.
  void (alias => {
    Game_Action.prototype.itemEffectSpecial = function(target, effect) {
      if (effect.dataId === Game_Action.SPECIAL_EFFECT_ESCAPE) {
        if (Math.random() >= getResistEscape(target)) {
          target.escape();
          this.makeSuccess(target);
        }
      } else
        alias.apply(this, arguments);
    };
  })(Game_Action.prototype.itemEffectSpecial);

})();
